import type { AgentTraceEnvelopeV1 } from "./agent-analytics";

export interface ArizePublicConfig {
	enabled: boolean;
	reason: string;
	evaluationContentEnabled: boolean;
	maxContentChars: number;
	rateLimitPerMinute: number;
}

export type ArizeTraceStatus =
	| { state: "idle" | "disabled" | "sent" }
	| { state: "failed"; retry: () => Promise<void>; turnOff: () => void };

const CONFIG_PATH = "/api/observability/v1/arize/config";
const TRACE_PATH = "/api/observability/v1/arize/traces";

export async function getArizePublicConfig(fetcher: typeof fetch = fetch): Promise<ArizePublicConfig> {
	try {
		const response = await fetcher(CONFIG_PATH, { credentials: "same-origin" });
		if (!response.ok) throw new Error("unavailable");
		const parsed = await response.json() as Partial<ArizePublicConfig>;
		return {
			enabled: parsed.enabled === true,
			reason: typeof parsed.reason === "string" ? parsed.reason : "unavailable",
			evaluationContentEnabled: parsed.evaluationContentEnabled === true,
			maxContentChars: typeof parsed.maxContentChars === "number" ? parsed.maxContentChars : 16_000,
			rateLimitPerMinute: typeof parsed.rateLimitPerMinute === "number" ? parsed.rateLimitPerMinute : 30,
		};
	} catch {
		return { enabled: false, reason: "unavailable", evaluationContentEnabled: false, maxContentChars: 16_000, rateLimitPerMinute: 30 };
	}
}

export class ArizeTraceClient {
	private failed: AgentTraceEnvelopeV1 | undefined;

	constructor(
		private readonly fetcher: typeof fetch = fetch,
		private readonly onStatus: (status: ArizeTraceStatus) => void = () => undefined,
		private readonly onTurnOff: () => void = () => undefined,
	) {}

	turnOff(): void {
		this.failed = undefined;
		this.onTurnOff();
	}

	async submit(envelope: AgentTraceEnvelopeV1, config: ArizePublicConfig, preferenceEnabled: boolean): Promise<void> {
		if (!config.enabled || !preferenceEnabled) {
			this.onStatus({ state: "disabled" });
			return;
		}
		const payload = !config.evaluationContentEnabled
			? { ...envelope, evaluation_content: undefined }
			: envelope.evaluation_content
				? {
					...envelope,
					evaluation_content: {
						input: envelope.evaluation_content.input.slice(0, config.maxContentChars),
						output: envelope.evaluation_content.output.slice(0, config.maxContentChars),
					},
				}
				: envelope;
		try {
			const response = await this.fetcher(TRACE_PATH, {
				method: "POST",
				credentials: "same-origin",
				headers: { "content-type": "application/json" },
				body: JSON.stringify(payload),
			});
			if (!response.ok) throw new Error(`status_${response.status}`);
			this.failed = undefined;
			this.onStatus({ state: "sent" });
		} catch {
			this.failed = payload;
			this.onStatus({
				state: "failed",
				retry: async () => {
					if (this.failed) await this.submit(this.failed, config, preferenceEnabled);
				},
				turnOff: () => {
					this.turnOff();
				},
			});
		}
	}
}
	];
}

let testTraceExporter: ((spans: readonly ArizeSpanRecord[]) => Promise<void> | void) | undefined;

export function setAgentTraceExporterForTests(
	exporter?: (spans: readonly ArizeSpanRecord[]) => Promise<void> | void,
): void {
	testTraceExporter = exporter;
}

/**
 * Best-effort OTLP export. The tracer provider is deliberately short-lived so
 * a serverless request cannot leak global instrumentation into another route.
 */
export async function exportAgentTrace(envelope: AgentTraceEnvelope, config = readServerArizeConfig()): Promise<void> {
	const records = mapAgentTraceToSpans(envelope, config.evaluationContentEnabled);
	if (testTraceExporter) {
		await testTraceExporter(records);
		return;
	}
	if (!config.enabled || !config.apiKey || !config.spaceId || !config.endpoint || !config.projectName) return;
	const exporter = new OTLPTraceExporter({ url: config.endpoint, headers: { "arize-space-id": config.spaceId, "arize-api-key": config.apiKey } });
	const provider = new NodeTracerProvider({
		resource: resourceFromAttributes({ "openinference.project.name": config.projectName }),
		spanProcessors: [new SimpleSpanProcessor(exporter)],
	});
	const tracer = provider.getTracer("keating.arize.relay");
	const root = tracer.startSpan(records[0].name);
	root.setAttributes({ "openinference.span.kind": "AGENT", ...records[0].attributes });
	const rootContext = trace.setSpan(context.active(), root);
	for (const record of records.slice(1)) {
		const child = tracer.startSpan(record.name, undefined, rootContext);
		child.setAttributes({ "openinference.span.kind": record.kind, ...record.attributes });
		if (record.status === "error") child.setStatus({ code: SpanStatusCode.ERROR });
		child.end();
	}
	if (records[0].status === "error") root.setStatus({ code: SpanStatusCode.ERROR });
	root.end();
	await provider.forceFlush();
	await provider.shutdown();
}

export function validateTracePayload(value: unknown, config = readServerArizeConfig()): AgentTraceEnvelope {
	const parsed = agentTraceEnvelopeSchema.parse(value);
	if (!config.evaluationContentEnabled) return { ...parsed, evaluation_content: undefined };
	const cap = config.maxContentChars;
	if (parsed.evaluation_content && (parsed.evaluation_content.input.length > cap || parsed.evaluation_content.output.length > cap)) throw new Error("content exceeds configured limit");
	return parsed;
}

export function requestWithinLimit(contentLength: string | undefined): boolean {
	if (!contentLength) return true;
	const parsed = Number(contentLength);
	return Number.isInteger(parsed) && parsed >= 0 && parsed <= MAX_BODY_BYTES;
}

export class IpRateLimiter {
	private readonly records = new Map<string, number[]>();
	allow(key: string, limit: number, now = Date.now()): boolean {
		const cutoff = now - 60_000;
		const current = (this.records.get(key) ?? []).filter((time) => time > cutoff);
		if (current.length >= limit) { this.records.set(key, current); return false; }
		current.push(now); this.records.set(key, current); return true;
	}
}

